// SISTEMA PACIENTES | MIGRAR HISTORIAL DE GOOGLE SHEETS AL CRM
// Lee todas las filas de la hoja "leads" y devuelve una tarjeta por contacto.
const text = (value) => String(value ?? '').trim();
const digits = (value) => text(value).replace(/\D/g, '');

return $input.all().flatMap(({ json: fila }) => {
  const waId = digits(fila.wa_id || fila.telefono);
  const subscriberId = Number(waId);
  if (!Number.isSafeInteger(subscriberId)) return [];

  const estado = text(fila.estado).toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  let stage = 'contactos_nuevos';
  if (estado === 'CALIFICADO') stage = 'calificado';
  else if (estado === 'LINK_ENVIADO') stage = 'link_enviado';
  else if (estado === 'AGENDO') stage = 'cita_agendada';
  else if (estado === 'FRIO') stage = 'no_interesado';

  const specialty = text(fila.especialidad);
  const businessType = text(fila.tipo_negocio);
  return [{ json: {
    p_company_key: 'sistema-pacientes',
    p_subscriber_id: subscriberId,
    p_whatsapp_phone: waId,
    p_nombre_paciente: text(fila.nombre) || `Contacto ${waId.slice(-4)}`,
    p_service: specialty || businessType || 'Sistema de captación de pacientes',
    p_kanban_stage: stage,
    p_source: text(fila.origen) || 'Histórico Google Sheets',
    p_ultimo_mensaje_cliente: text(fila.ultimo_mensaje),
    p_ultimo_mensaje_bot: text(fila.ultima_respuesta_bot),
    p_last_activity_at: text(fila.ultimo_mensaje_ts) || text(fila.fecha) || new Date().toISOString(),
    p_raw_payload: {
      especialidad: specialty || null, tipo_negocio: businessType || null,
      ciudad: text(fila.ciudad) || null, tratamiento_principal: text(fila.tratamiento_principal) || null,
      ticket_aprox: text(fila.ticket_aprox) || null, recomendacion: text(fila.recomendacion) || null,
      estado_sistema_pacientes: text(fila.estado) || 'NUEVO', lead_caliente: text(fila.lead_caliente) || 'no',
      link_enviado_ts: text(fila.link_enviado_ts) || null, fuente: 'Histórico Google Sheets'
    }
  } }];
});
